-- Financial and inventory retries bind employee identity and all arguments.
-- Existing balances, ledger writes, approval separation and row-lock ordering are preserved.
set statement_timeout='30s';
set lock_timeout='5s';


create or replace function public.salon_checkout_order(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_order_id bigint,p_request_key text,p_payments jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_order public.salon_orders;v_request public.salon_operation_requests;v_payment jsonb;v_account public.salon_member_accounts;v_payment_id bigint;v_method text;v_amount numeric(12,2);v_tendered numeric(12,2);v_change numeric(12,2);v_units numeric(12,3);v_account_id bigint;v_reference text;v_paid numeric(12,2);v_total_tendered numeric(12,2):=0;v_total_change numeric(12,2):=0;v_stock record;v_balance public.salon_inventory_balances;v_stock_ledger_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','checkout');
 v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'checkout','checkout_payload',hashtextextended(jsonb_build_object('order',p_order_id,'payments',p_payments)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_order_id',p_order_id,'p_payments',p_payments),'orders','checkout');if v_request.completed_at is not null then return v_request.response_json;end if;
 select * into v_order from public.salon_orders o where o.organization_id=p_organization_id and o.store_id=p_store_id and o.id=p_order_id for update;if not found then raise exception '订单不存在或不属于当前门店';end if;if v_order.status<>'awaiting_payment' then raise exception '只有待收银订单可以确认收款';end if;if jsonb_typeof(p_payments)<>'array' or jsonb_array_length(p_payments)=0 or jsonb_array_length(p_payments)>10 then raise exception '支付明细必须为1至10项';end if;
 select round(coalesce(sum((x->>'amount')::numeric),0),2) into v_paid from jsonb_array_elements(p_payments) x;if v_paid<>v_order.payable_total then raise exception '支付合计必须等于应收金额';end if;
 if exists(select 1 from jsonb_array_elements(p_payments) x where x->>'method' in ('member_value','member_units')) and not exists(select 1 from public.salon_customers c where c.organization_id=p_organization_id and c.id=v_order.customer_id and c.status='active') then raise exception '顾客当前不可使用会员账户';end if;
 perform 1 from public.salon_member_accounts a where a.organization_id=p_organization_id and a.id in(select distinct nullif(x->>'accountId','')::bigint from jsonb_array_elements(p_payments) x) order by a.id for update;
 for v_payment in select value from jsonb_array_elements(p_payments) loop
  v_method:=v_payment->>'method';v_amount:=round(coalesce(nullif(v_payment->>'amount','')::numeric,0),2);v_tendered:=round(coalesce(nullif(v_payment->>'tenderedAmount','')::numeric,v_amount),2);v_units:=round(coalesce(nullif(v_payment->>'units','')::numeric,0),3);v_account_id:=nullif(v_payment->>'accountId','')::bigint;v_reference:=btrim(coalesce(v_payment->>'externalReference',''));
  if v_method not in ('cash','wechat','alipay','member_value','member_units') or v_amount<=0 then raise exception '支付方式或金额无效';end if;
  if v_method='cash' then if v_tendered<v_amount then raise exception '现金实收不能低于本次支付金额';end if;v_change:=v_tendered-v_amount;elsif v_tendered<>v_amount then raise exception '非现金支付实收必须等于支付金额';else v_change:=0;end if;
  if v_method in ('wechat','alipay') and v_reference='' then raise exception '电子支付必须填写交易凭证号';end if;if v_method in ('cash','member_value','member_units') and v_reference<>'' then raise exception '当前支付方式不应填写电子凭证号';end if;
  if v_method in ('member_value','member_units') then select * into v_account from public.salon_member_accounts a where a.organization_id=p_organization_id and a.id=v_account_id and a.customer_id=v_order.customer_id and a.status='active' and (a.home_store_id=p_store_id or a.usable_scope='organization');if not found or (v_account.expires_on is not null and v_account.expires_on<current_date) then raise exception '会员账户不可核销';end if;if v_method='member_value' and (v_account.account_type<>'stored_value' or v_account.cash_balance<v_amount) then raise exception '储值余额不足或卡类型错误';end if;if v_method='member_units' and (v_account.account_type not in ('times_card','package') or v_units<=0 or v_account.remaining_units<v_units) then raise exception '次卡余次不足或卡类型错误';end if;end if;
  begin insert into public.salon_payments(organization_id,store_id,order_id,payment_method,amount,tendered_amount,change_amount,external_reference,member_account_id,member_units,status,confirmed_at) values(p_organization_id,p_store_id,p_order_id,v_method,v_amount,v_tendered,v_change,v_reference,v_account_id,v_units,'confirmed',now()) returning id into v_payment_id;exception when unique_violation then raise exception '电子支付凭证号已经使用';end;
  if v_method='member_value' then update public.salon_member_accounts set cash_balance=cash_balance-v_amount where organization_id=p_organization_id and id=v_account.id;insert into public.salon_account_ledger(organization_id,store_id,account_id,order_id,payment_id,entry_type,cash_delta,reason) values(p_organization_id,p_store_id,v_account.id,p_order_id,v_payment_id,'consume',-v_amount,'订单收银');elsif v_method='member_units' then update public.salon_member_accounts set remaining_units=remaining_units-v_units where organization_id=p_organization_id and id=v_account.id;insert into public.salon_account_ledger(organization_id,store_id,account_id,order_id,payment_id,entry_type,units_delta,reason) values(p_organization_id,p_store_id,v_account.id,p_order_id,v_payment_id,'consume',-v_units,'订单核销');end if;
  v_total_tendered:=v_total_tendered+v_tendered;v_total_change:=v_total_change+v_change;
 end loop;
 for v_stock in select l.catalog_item_id,sum(l.quantity)::numeric(14,3) quantity from public.salon_order_lines l where l.organization_id=p_organization_id and l.order_id=p_order_id and l.item_type='product' group by l.catalog_item_id order by l.catalog_item_id loop
  if not exists(select 1 from public.salon_catalog_store_settings s where s.organization_id=p_organization_id and s.store_id=p_store_id and s.catalog_item_id=v_stock.catalog_item_id and s.status='active' and s.stock_tracked) then raise exception '订单商品未启用当前门店库存';end if;select * into v_balance from public.salon_inventory_balances b where b.organization_id=p_organization_id and b.store_id=p_store_id and b.catalog_item_id=v_stock.catalog_item_id for update;if not found or v_balance.quantity<v_stock.quantity then raise exception '商品库存不足，收银已回滚';end if;
  update public.salon_inventory_balances set quantity=quantity-v_stock.quantity,updated_at=now() where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=v_stock.catalog_item_id;insert into public.salon_inventory_ledger(organization_id,store_id,catalog_item_id,movement_type,quantity_delta,quantity_before,quantity_after,order_id,reason) values(p_organization_id,p_store_id,v_stock.catalog_item_id,'sale',-v_stock.quantity,v_balance.quantity,v_balance.quantity-v_stock.quantity,p_order_id,'订单收银自动出库') returning id into v_stock_ledger_id;
 end loop;
 update public.salon_orders set status='paid',paid_at=now(),updated_at=now() where organization_id=p_organization_id and id=p_order_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'order',p_order_id::text,'checkout',jsonb_build_object('total',v_paid,'tendered',v_total_tendered,'change',v_total_change,'requestKey',p_request_key),'订单收银');v_response:=jsonb_build_object('orderId',p_order_id,'status','paid','paid',v_paid,'tendered',v_total_tendered,'change',v_total_change);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_move_inventory(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_catalog_item_id bigint,p_request_key text,p_movement_type text,p_quantity numeric,p_order_id bigint,p_reason text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_balance public.salon_inventory_balances;v_delta numeric(14,3);v_after numeric(14,3);v_ledger_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'inventory','write');v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'inventory_move','catalog_item',p_catalog_item_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_catalog_item_id',p_catalog_item_id,'p_movement_type',p_movement_type,'p_quantity',p_quantity,'p_order_id',p_order_id,'p_reason',p_reason),'inventory','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 if p_movement_type not in ('receive','sale','consume','refund') or p_quantity is null or p_quantity<=0 then raise exception '库存操作类型或数量无效';end if;if nullif(btrim(p_reason),'') is null then raise exception '库存原因不能为空';end if;
 if not exists(select 1 from public.salon_catalog_store_settings s join public.salon_catalog_items i on i.organization_id=s.organization_id and i.id=s.catalog_item_id where s.organization_id=p_organization_id and s.store_id=p_store_id and s.catalog_item_id=p_catalog_item_id and s.status='active' and s.stock_tracked and i.item_type='product' and i.status='active') then raise exception '当前门店未启用该商品库存';end if;
 select * into v_balance from public.salon_inventory_balances b where b.organization_id=p_organization_id and b.store_id=p_store_id and b.catalog_item_id=p_catalog_item_id for update;if not found then raise exception '库存余额不存在';end if;
 v_delta:=case when p_movement_type in ('receive','refund') then round(p_quantity,3) else -round(p_quantity,3) end;v_after:=v_balance.quantity+v_delta;if v_after<0 then raise exception '库存不足，不能出库';end if;
 update public.salon_inventory_balances set quantity=v_after,updated_at=now() where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=p_catalog_item_id;
 insert into public.salon_inventory_ledger(organization_id,store_id,catalog_item_id,movement_type,quantity_delta,quantity_before,quantity_after,order_id,reason) values(p_organization_id,p_store_id,p_catalog_item_id,p_movement_type,v_delta,v_balance.quantity,v_after,p_order_id,btrim(p_reason)) returning id into v_ledger_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'inventory_ledger',v_ledger_id::text,'create',jsonb_build_object('before',v_balance.quantity,'after',v_after,'requestKey',p_request_key),btrim(p_reason));
 v_response:=jsonb_build_object('ledgerId',v_ledger_id,'quantityBefore',v_balance.quantity,'quantityAfter',v_after);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_count_inventory(
 p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_catalog_item_id bigint,p_request_key text,p_counted numeric,p_reason text
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_balance public.salon_inventory_balances;v_ledger_id bigint;v_reason text:=btrim(coalesce(p_reason,''));v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'inventory','write');
 v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'inventory_count','catalog_item',p_catalog_item_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_catalog_item_id',p_catalog_item_id,'p_counted',p_counted,'p_reason',p_reason),'inventory','write');
 if v_request.completed_at is not null then return v_request.response_json;end if;
 if p_counted is null or p_counted<0 or v_reason='' then raise exception '盘点数量或原因无效';end if;
 if not exists(select 1 from public.salon_catalog_store_settings s where s.organization_id=p_organization_id and s.store_id=p_store_id and s.catalog_item_id=p_catalog_item_id and s.status='active' and s.stock_tracked) then raise exception '当前门店未启用该商品库存';end if;
 select * into v_balance from public.salon_inventory_balances b where b.organization_id=p_organization_id and b.store_id=p_store_id and b.catalog_item_id=p_catalog_item_id for update;
 if not found then raise exception '库存余额不存在';end if;
 if round(p_counted,3)=v_balance.quantity then raise exception '盘点数量与当前库存一致';end if;
 insert into public.salon_inventory_ledger(organization_id,store_id,catalog_item_id,movement_type,quantity_delta,quantity_before,quantity_after,reason) values(p_organization_id,p_store_id,p_catalog_item_id,'count_adjustment',round(p_counted,3)-v_balance.quantity,v_balance.quantity,round(p_counted,3),v_reason) returning id into v_ledger_id;
 update public.salon_inventory_balances set quantity=round(p_counted,3),updated_at=now() where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=p_catalog_item_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'inventory_ledger',v_ledger_id::text,'count',jsonb_build_object('before',v_balance.quantity,'after',round(p_counted,3),'requestKey',p_request_key),v_reason);
 v_response:=jsonb_build_object('ledgerId',v_ledger_id,'quantityBefore',v_balance.quantity,'quantityAfter',round(p_counted,3));update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_open_member_account(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_customer_id bigint,p_request_key text,p_account_type text,p_account_no text,p_display_name text,p_usable_scope text default 'store',p_expires_on date default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_id bigint;v_no text:=upper(btrim(coalesce(p_account_no,'')));v_name text:=btrim(coalesce(p_display_name,''));v_hash bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'members','write');
 if p_account_type not in ('stored_value','package','times_card') or v_no='' or length(v_no)>50 or v_name='' or p_usable_scope not in ('store','organization') then raise exception '会员账户参数无效';end if;
 if p_expires_on is not null and p_expires_on<current_date then raise exception '会员账户有效期不能早于今天';end if;
 if not exists(select 1 from public.salon_customers c join public.salon_customer_store_relations r on r.organization_id=c.organization_id and r.customer_id=c.id where c.organization_id=p_organization_id and c.id=p_customer_id and c.status='active' and r.store_id=p_store_id) then raise exception '顾客不存在、已冻结或不属于当前门店';end if;
 v_hash:=hashtextextended(jsonb_build_object('customer',p_customer_id,'type',p_account_type,'no',v_no,'name',v_name,'scope',p_usable_scope,'expires',p_expires_on)::text,0);v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'member_open','member_payload',v_hash,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_customer_id',p_customer_id,'p_account_type',p_account_type,'p_account_no',p_account_no,'p_display_name',p_display_name,'p_usable_scope',p_usable_scope,'p_expires_on',p_expires_on),'members','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 begin insert into public.salon_member_accounts(organization_id,customer_id,account_type,account_no,display_name,home_store_id,usable_scope,remaining_units,expires_on) values(p_organization_id,p_customer_id,p_account_type,v_no,v_name,p_store_id,p_usable_scope,case when p_account_type in ('package','times_card') then 0 else null end,p_expires_on) returning id into v_id;exception when unique_violation then raise exception '会员账户编号已经存在';end;
 insert into public.salon_account_ledger(organization_id,store_id,account_id,entry_type,reason) values(p_organization_id,p_store_id,v_id,'open','会员账户开户');
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'member_account',v_id::text,'open',jsonb_build_object('accountType',p_account_type,'accountNo',v_no,'usableScope',p_usable_scope));
 v_response:=jsonb_build_object('accountId',v_id,'accountNo',v_no,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_recharge_member_account(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_account_id bigint,p_request_key text,p_paid_amount numeric,p_cash_added numeric,p_bonus_added numeric,p_units_added numeric,p_payment_method text,p_external_reference text,p_reason text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_request public.salon_operation_requests;v_account public.salon_member_accounts;v_recharge_id bigint;v_reason text:=btrim(coalesce(p_reason,''));v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'members','recharge');v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'member_recharge','member_recharge_payload',hashtextextended(jsonb_build_object('account',p_account_id,'paid',p_paid_amount,'cash',p_cash_added,'bonus',p_bonus_added,'units',p_units_added,'method',p_payment_method,'reference',btrim(coalesce(p_external_reference,'')),'reason',v_reason)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_account_id',p_account_id,'p_paid_amount',p_paid_amount,'p_cash_added',p_cash_added,'p_bonus_added',p_bonus_added,'p_units_added',p_units_added,'p_payment_method',p_payment_method,'p_external_reference',p_external_reference,'p_reason',p_reason),'members','recharge');if v_request.completed_at is not null then return v_request.response_json;end if;
 if p_paid_amount is null or p_cash_added is null or p_bonus_added is null or p_units_added is null or least(p_paid_amount,p_cash_added,p_bonus_added,p_units_added)<0 or p_paid_amount+p_bonus_added+p_units_added<=0 or p_payment_method not in ('cash','wechat','alipay','bank','other','no_payment') or v_reason='' then raise exception '充值金额、方式或原因无效';end if;
 if (p_paid_amount=0)<>(p_payment_method='no_payment') then raise exception '无实收充值必须使用无支付方式';end if;
 select * into v_account from public.salon_member_accounts a where a.organization_id=p_organization_id and a.id=p_account_id and a.status='active' and (a.home_store_id=p_store_id or a.usable_scope='organization') for update;if not found then raise exception '会员账户不存在、已冻结或当前门店不可用';end if;
 if v_account.expires_on is not null and v_account.expires_on<current_date then raise exception '会员账户已经过期';end if;
 if v_account.account_type='stored_value' then if p_cash_added<>p_paid_amount or p_units_added<>0 then raise exception '储值卡充值金额不匹配';end if;else if p_cash_added<>0 or p_bonus_added<>0 or p_units_added<=0 then raise exception '次卡或套餐充值必须增加次数';end if;end if;
 insert into public.salon_member_recharges(organization_id,store_id,account_id,paid_amount,cash_added,bonus_added,units_added,payment_method,external_reference,reason) values(p_organization_id,p_store_id,p_account_id,round(p_paid_amount,2),round(p_cash_added,2),round(p_bonus_added,2),round(p_units_added,3),p_payment_method,btrim(coalesce(p_external_reference,'')),v_reason) returning id into v_recharge_id;
 update public.salon_member_accounts set cash_balance=cash_balance+round(p_cash_added,2),bonus_balance=bonus_balance+round(p_bonus_added,2),remaining_units=case when remaining_units is null then null else remaining_units+round(p_units_added,3) end where organization_id=p_organization_id and id=p_account_id;
 insert into public.salon_account_ledger(organization_id,store_id,account_id,entry_type,cash_delta,bonus_delta,units_delta,recharge_id,reason) values(p_organization_id,p_store_id,p_account_id,case when p_paid_amount>0 then 'recharge' else 'bonus' end,round(p_cash_added,2),round(p_bonus_added,2),round(p_units_added,3),v_recharge_id,v_reason);
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'member_recharge',v_recharge_id::text,'create',jsonb_build_object('accountId',p_account_id,'paidAmount',p_paid_amount,'paymentMethod',p_payment_method,'requestKey',p_request_key),v_reason);
 v_response:=jsonb_build_object('rechargeId',v_recharge_id,'accountId',p_account_id,'cashBalance',v_account.cash_balance+round(p_cash_added,2),'bonusBalance',v_account.bonus_balance+round(p_bonus_added,2),'remainingUnits',case when v_account.remaining_units is null then null else v_account.remaining_units+round(p_units_added,3) end);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_set_member_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_account_id bigint,p_request_key text,p_status text,p_reason text)
returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_request public.salon_operation_requests;v_before text;v_response jsonb;begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'members','write');v_request:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'member_status','member_status_'||coalesce(p_status,''),p_account_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_account_id',p_account_id,'p_status',p_status,'p_reason',p_reason),'members','write');if v_request.completed_at is not null then return v_request.response_json;end if;
 if p_status not in ('active','frozen') or nullif(btrim(p_reason),'') is null then raise exception '会员账户状态或原因无效';end if;select status into v_before from public.salon_member_accounts where organization_id=p_organization_id and id=p_account_id and (home_store_id=p_store_id or usable_scope='organization') for update;if not found then raise exception '会员账户不存在或当前门店不可管理';end if;if v_before=p_status then raise exception '会员账户已经是目标状态';end if;
 update public.salon_member_accounts set status=p_status where organization_id=p_organization_id and id=p_account_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'member_account',p_account_id::text,'status_change',jsonb_build_object('status',v_before),jsonb_build_object('status',p_status),btrim(p_reason));v_response:=jsonb_build_object('accountId',p_account_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_request.id;return v_response;
end $$;

create or replace function public.salon_submit_refund_request(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_order_id bigint,p_request_key text,p_refund_type text,p_reason text,p_lines jsonb default '[]',p_payments jsonb default '[]') returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_req public.salon_operation_requests;v_order public.salon_orders;v_id bigint;v_row jsonb;v_line public.salon_order_lines;v_payment public.salon_payments;v_qty numeric;v_amount numeric;v_units numeric;v_line_total numeric:=0;v_payment_total numeric:=0;v_used numeric;v_response jsonb;begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','refund_request');if p_refund_type not in ('full','partial') or nullif(btrim(p_reason),'') is null then raise exception '退款类型或原因无效';end if;
 v_req:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'refund_request','refund_request_payload',hashtextextended(jsonb_build_object('order',p_order_id,'type',p_refund_type,'reason',btrim(p_reason),'lines',p_lines,'payments',p_payments)::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_order_id',p_order_id,'p_refund_type',p_refund_type,'p_reason',p_reason,'p_lines',p_lines,'p_payments',p_payments),'orders','refund_request');if v_req.completed_at is not null then return v_req.response_json;end if;
 select * into v_order from public.salon_orders where organization_id=p_organization_id and store_id=p_store_id and id=p_order_id for update;if not found or v_order.status<>'paid' then raise exception '只有当前门店已支付订单可以申请退款';end if;
 insert into public.salon_refund_requests(organization_id,store_id,order_id,refund_type,requested_amount,reason,created_by_staff_id) values(p_organization_id,p_store_id,p_order_id,p_refund_type,0,btrim(p_reason),p_actor_staff_id) returning id into v_id;
 if p_refund_type='full' then
  if exists(select 1 from public.salon_refund_requests r where r.organization_id=p_organization_id and r.order_id=p_order_id and r.id<>v_id and r.status in ('submitted','approved','executed')) then raise exception '订单已有未结束退款申请';end if;
  insert into public.salon_refund_request_lines(organization_id,refund_request_id,order_line_id,quantity,refund_amount,item_code,item_name,item_type) select p_organization_id,v_id,l.id,l.quantity,l.line_total,l.item_code,l.item_name,l.item_type from public.salon_order_lines l where l.organization_id=p_organization_id and l.order_id=p_order_id;v_line_total:=v_order.payable_total;
  insert into public.salon_refund_request_payments(organization_id,refund_request_id,original_payment_id,refund_amount,refund_units,payment_method) select p_organization_id,v_id,p.id,p.amount,p.member_units,p.payment_method from public.salon_payments p where p.organization_id=p_organization_id and p.order_id=p_order_id and p.reversal_of_id is null;v_payment_total:=v_order.payable_total;
 else
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 or jsonb_typeof(p_payments)<>'array' or jsonb_array_length(p_payments)=0 then raise exception '部分退款必须填写商品项目和原支付分配';end if;
  for v_row in select value from jsonb_array_elements(p_lines) loop select * into v_line from public.salon_order_lines where organization_id=p_organization_id and order_id=p_order_id and id=nullif(v_row->>'orderLineId','')::bigint;if not found then raise exception '退款明细不属于原订单';end if;v_qty:=round(coalesce(nullif(v_row->>'quantity','')::numeric,0),3);v_amount:=round(coalesce(nullif(v_row->>'amount','')::numeric,0),2);select coalesce(sum(x.quantity),0),coalesce(sum(x.refund_amount),0) into v_used,v_payment_total from public.salon_refund_request_lines x join public.salon_refund_requests r on r.organization_id=x.organization_id and r.id=x.refund_request_id where x.organization_id=p_organization_id and r.order_id=p_order_id and x.order_line_id=v_line.id and r.status in ('submitted','approved','executed');if v_qty<=0 or v_amount<=0 or v_qty+v_used>v_line.quantity or v_amount+v_payment_total>v_line.line_total then raise exception '退款数量或金额超过可退范围';end if;insert into public.salon_refund_request_lines values(p_organization_id,v_id,v_line.id,v_qty,v_amount,v_line.item_code,v_line.item_name,v_line.item_type);v_line_total:=v_line_total+v_amount;end loop;
  v_payment_total:=0;for v_row in select value from jsonb_array_elements(p_payments) loop select * into v_payment from public.salon_payments where organization_id=p_organization_id and order_id=p_order_id and id=nullif(v_row->>'originalPaymentId','')::bigint and reversal_of_id is null;if not found then raise exception '退款支付分配不属于原订单';end if;v_amount:=round(coalesce(nullif(v_row->>'amount','')::numeric,0),2);v_units:=round(coalesce(nullif(v_row->>'units','')::numeric,0),3);select coalesce(sum(x.refund_amount),0) into v_used from public.salon_refund_request_payments x join public.salon_refund_requests r on r.organization_id=x.organization_id and r.id=x.refund_request_id where x.organization_id=p_organization_id and r.order_id=p_order_id and x.original_payment_id=v_payment.id and r.status in ('submitted','approved','executed');if v_amount<=0 or v_amount+v_used>v_payment.amount or (v_payment.payment_method='member_units' and (v_units<=0 or v_units>v_payment.member_units)) then raise exception '退款支付金额或次数超过可退范围';end if;insert into public.salon_refund_request_payments values(p_organization_id,v_id,v_payment.id,v_amount,v_units,v_payment.payment_method);v_payment_total:=v_payment_total+v_amount;end loop;
  if round(v_line_total,2)<>round(v_payment_total,2) then raise exception '退款明细金额必须等于原支付分配金额';end if;
 end if;
 update public.salon_refund_requests set requested_amount=round(v_line_total,2) where id=v_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'refund_request',v_id::text,'submit',jsonb_build_object('orderId',p_order_id,'type',p_refund_type,'amount',round(v_line_total,2)),btrim(p_reason));v_response:=jsonb_build_object('refundRequestId',v_id,'status','submitted','requestedAmount',round(v_line_total,2));update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_req.id;return v_response;
end $$;

create or replace function public.salon_review_refund_request(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_refund_request_id bigint,p_request_key text,p_decision text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_req public.salon_operation_requests;v_refund public.salon_refund_requests;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','refund_approve');if p_decision not in ('approved','rejected') or nullif(btrim(p_reason),'') is null then raise exception '审批决定或意见无效';end if;v_req:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'refund_review','refund_'||p_decision,p_refund_request_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_refund_request_id',p_refund_request_id,'p_decision',p_decision,'p_reason',p_reason),'orders','refund_approve');if v_req.completed_at is not null then return v_req.response_json;end if;select * into v_refund from public.salon_refund_requests where organization_id=p_organization_id and store_id=p_store_id and id=p_refund_request_id for update;if not found or v_refund.status<>'submitted' then raise exception '退款申请不存在或当前不可审批';end if;if v_refund.created_by_staff_id=p_actor_staff_id then raise exception '退款申请人与审批人不能为同一人';end if;update public.salon_refund_requests set status=p_decision,reviewed_by_staff_id=p_actor_staff_id,decision_reason=btrim(p_reason),reviewed_at=now() where id=p_refund_request_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'refund_request',p_refund_request_id::text,'review',jsonb_build_object('status','submitted'),jsonb_build_object('status',p_decision),btrim(p_reason));v_response:=jsonb_build_object('refundRequestId',p_refund_request_id,'status',p_decision);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_req.id;return v_response;end $$;

create or replace function public.salon_execute_refund_request(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_refund_request_id bigint,p_request_key text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_refund public.salon_refund_requests;v_order public.salon_orders;v_alloc record;v_payment public.salon_payments;v_original_ledger public.salon_account_ledger;v_reversal_payment_id bigint;v_paid_refunded numeric(12,2);v_stock record;v_sale public.salon_inventory_ledger;v_balance public.salon_inventory_balances;v_stock_refunded numeric(14,3);v_new_total numeric(12,2);v_status text;v_payment_count integer:=0;v_stock_count integer:=0;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'orders','refund_execute');
 v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'refund_execute','refund_request',p_refund_request_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_refund_request_id',p_refund_request_id),'orders','refund_execute');if v_op.completed_at is not null then return v_op.response_json;end if;
 select * into v_refund from public.salon_refund_requests r where r.organization_id=p_organization_id and r.store_id=p_store_id and r.id=p_refund_request_id for update;
 if not found or v_refund.status<>'approved' then raise exception '退款申请不存在或当前不可执行';end if;
 select * into v_order from public.salon_orders o where o.organization_id=p_organization_id and o.store_id=p_store_id and o.id=v_refund.order_id for update;
 if not found or v_order.status<>'paid' then raise exception '原订单不是可退款的已支付状态';end if;
 if v_order.refunded_total+v_refund.requested_amount>v_order.payable_total then raise exception '累计退款金额超过订单实收';end if;
 if exists(select 1 from public.salon_refund_request_lines l where l.organization_id=p_organization_id and l.refund_request_id=p_refund_request_id and l.item_type='product') then perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'inventory','write');end if;
 perform 1 from public.salon_member_accounts a where a.organization_id=p_organization_id and a.id in(select distinct p.member_account_id from public.salon_refund_request_payments x join public.salon_payments p on p.organization_id=x.organization_id and p.id=x.original_payment_id where x.organization_id=p_organization_id and x.refund_request_id=p_refund_request_id and p.member_account_id is not null) order by a.id for update;
 for v_alloc in select x.* from public.salon_refund_request_payments x where x.organization_id=p_organization_id and x.refund_request_id=p_refund_request_id order by x.original_payment_id loop
  select * into v_payment from public.salon_payments p where p.organization_id=p_organization_id and p.store_id=p_store_id and p.order_id=v_order.id and p.id=v_alloc.original_payment_id and p.reversal_of_id is null for update;if not found then raise exception '退款支付分配不属于原订单';end if;
  select coalesce(sum(x.refund_amount),0) into v_paid_refunded from public.salon_refund_request_payments x join public.salon_refund_requests r on r.organization_id=x.organization_id and r.id=x.refund_request_id where x.organization_id=p_organization_id and x.original_payment_id=v_payment.id and r.status='executed';
  if v_paid_refunded+v_alloc.refund_amount>v_payment.amount then raise exception '支付渠道累计退款超过原支付金额';end if;
  insert into public.salon_payments(organization_id,store_id,order_id,payment_method,amount,tendered_amount,change_amount,external_reference,member_account_id,member_units,status,reversal_of_id,refund_request_id,confirmed_at) values(p_organization_id,p_store_id,v_order.id,v_payment.payment_method,v_alloc.refund_amount,0,0,'',v_payment.member_account_id,v_alloc.refund_units,'confirmed',v_payment.id,p_refund_request_id,now()) returning id into v_reversal_payment_id;
  if v_payment.member_account_id is not null then
   select * into v_original_ledger from public.salon_account_ledger l where l.organization_id=p_organization_id and l.payment_id=v_payment.id for update;if not found then raise exception '原会员扣款流水不存在，不能自动返还';end if;
   if v_payment.payment_method='member_value' then update public.salon_member_accounts set cash_balance=cash_balance+v_alloc.refund_amount where organization_id=p_organization_id and id=v_payment.member_account_id;insert into public.salon_account_ledger(organization_id,store_id,account_id,order_id,payment_id,entry_type,cash_delta,reversal_of_id,refund_request_id,reason) values(p_organization_id,p_store_id,v_payment.member_account_id,v_order.id,v_reversal_payment_id,'refund',v_alloc.refund_amount,v_original_ledger.id,p_refund_request_id,v_refund.reason);
   elsif v_payment.payment_method='member_units' then update public.salon_member_accounts set remaining_units=remaining_units+v_alloc.refund_units where organization_id=p_organization_id and id=v_payment.member_account_id;insert into public.salon_account_ledger(organization_id,store_id,account_id,order_id,payment_id,entry_type,units_delta,reversal_of_id,refund_request_id,reason) values(p_organization_id,p_store_id,v_payment.member_account_id,v_order.id,v_reversal_payment_id,'refund',v_alloc.refund_units,v_original_ledger.id,p_refund_request_id,v_refund.reason);end if;
  end if;
  if v_paid_refunded+v_alloc.refund_amount=v_payment.amount then update public.salon_payments set status='reversed' where organization_id=p_organization_id and id=v_payment.id;end if;v_payment_count:=v_payment_count+1;
 end loop;
 for v_stock in select ol.catalog_item_id,sum(rl.quantity)::numeric(14,3) quantity from public.salon_refund_request_lines rl join public.salon_order_lines ol on ol.organization_id=rl.organization_id and ol.id=rl.order_line_id where rl.organization_id=p_organization_id and rl.refund_request_id=p_refund_request_id and rl.item_type='product' group by ol.catalog_item_id order by ol.catalog_item_id loop
  select * into v_sale from public.salon_inventory_ledger l where l.organization_id=p_organization_id and l.store_id=p_store_id and l.order_id=v_order.id and l.catalog_item_id=v_stock.catalog_item_id and l.movement_type='sale' and l.reversal_of_id is null order by l.id limit 1 for update;if not found then raise exception '原商品销售出库流水不存在';end if;
  select coalesce(sum(l.quantity_delta),0) into v_stock_refunded from public.salon_inventory_ledger l where l.organization_id=p_organization_id and l.reversal_of_id=v_sale.id and l.movement_type='refund';if v_stock_refunded+v_stock.quantity>-v_sale.quantity_delta then raise exception '商品累计退回数量超过原销售数量';end if;
  select * into v_balance from public.salon_inventory_balances b where b.organization_id=p_organization_id and b.store_id=p_store_id and b.catalog_item_id=v_stock.catalog_item_id for update;if not found then raise exception '商品库存余额不存在';end if;
  update public.salon_inventory_balances set quantity=quantity+v_stock.quantity,updated_at=now() where organization_id=p_organization_id and store_id=p_store_id and catalog_item_id=v_stock.catalog_item_id;
  insert into public.salon_inventory_ledger(organization_id,store_id,catalog_item_id,movement_type,quantity_delta,quantity_before,quantity_after,order_id,reversal_of_id,refund_request_id,reason) values(p_organization_id,p_store_id,v_stock.catalog_item_id,'refund',v_stock.quantity,v_balance.quantity,v_balance.quantity+v_stock.quantity,v_order.id,v_sale.id,p_refund_request_id,v_refund.reason);v_stock_count:=v_stock_count+1;
 end loop;
 v_new_total:=v_order.refunded_total+v_refund.requested_amount;v_status:=case when v_new_total=v_order.payable_total then 'reversed' else 'paid' end;
 update public.salon_orders set refunded_total=v_new_total,status=v_status,updated_at=now() where organization_id=p_organization_id and id=v_order.id;
 update public.salon_refund_requests set status='executed',executed_at=now() where organization_id=p_organization_id and id=p_refund_request_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'refund_request',p_refund_request_id::text,'execute',jsonb_build_object('status','approved','orderRefundedTotal',v_order.refunded_total),jsonb_build_object('status','executed','orderStatus',v_status,'orderRefundedTotal',v_new_total,'payments',v_payment_count,'stockReturns',v_stock_count),v_refund.reason);
 v_response:=jsonb_build_object('refundRequestId',p_refund_request_id,'status','executed','orderId',v_order.id,'orderStatus',v_status,'refundedAmount',v_refund.requested_amount,'orderRefundedTotal',v_new_total,'reversedPayments',v_payment_count,'returnedStock',v_stock_count);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end $$;

create or replace function public.salon_add_finance_entry(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_entry_date date,p_entry_type text,p_category text,p_amount numeric,p_note text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'finance','write');
 if p_entry_date is null or p_entry_type not in('income','expense') or p_amount is null or round(p_amount,2)<=0 or nullif(btrim(coalesce(p_category,'')),'') is null or nullif(btrim(coalesce(p_note,'')),'') is null then raise exception '收支记录参数无效';end if;
 v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'finance_entry','finance_payload',hashtextextended(jsonb_build_object('date',p_entry_date,'type',p_entry_type,'category',btrim(p_category),'amount',round(p_amount,2),'note',btrim(p_note))::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_entry_date',p_entry_date,'p_entry_type',p_entry_type,'p_category',p_category,'p_amount',p_amount,'p_note',p_note),'finance','write');if v_op.completed_at is not null then return v_op.response_json;end if;
 insert into public.salon_finance_entries(organization_id,store_id,entry_date,entry_type,category,amount,note,created_by_staff_id) values(p_organization_id,p_store_id,p_entry_date,p_entry_type,btrim(p_category),round(p_amount,2),btrim(p_note),p_actor_staff_id) returning id into v_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'finance_entry',v_id::text,'create',jsonb_build_object('date',p_entry_date,'type',p_entry_type,'category',btrim(p_category),'amount',round(p_amount,2)),btrim(p_note));
 v_response:=jsonb_build_object('financeEntryId',v_id,'status','recorded');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end $$;

create or replace function public.salon_generate_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_staff_id bigint,p_request_key text,p_month date,p_bonus numeric default 0,p_deduction numeric default 0,p_reason text default '') returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_timezone text;v_gross numeric(12,2);v_refund numeric(12,2);v_commission numeric(12,2);v_id bigint;v_total numeric(12,2);v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','generate');if p_month is null or extract(day from p_month)<>1 or coalesce(p_bonus,0)<0 or coalesce(p_deduction,0)<0 or ((coalesce(p_bonus,0)>0 or coalesce(p_deduction,0)>0) and nullif(btrim(coalesce(p_reason,'')),'') is null) then raise exception '工资试算参数无效';end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'payroll_generate','payroll_payload',hashtextextended(jsonb_build_object('staff',p_staff_id,'month',p_month,'bonus',round(coalesce(p_bonus,0),2),'deduction',round(coalesce(p_deduction,0),2),'reason',btrim(coalesce(p_reason,'')))::text,0),p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_staff_id',p_staff_id,'p_month',p_month,'p_bonus',p_bonus,'p_deduction',p_deduction,'p_reason',p_reason),'payroll','generate');if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_staff_id for update;if not found then raise exception '员工不存在或不属于当前门店';end if;select timezone into v_timezone from public.salon_stores where organization_id=p_organization_id and id=p_store_id;select coalesce(round(sum(gross_amount) filter(where entry_type='sale'),2),0),coalesce(round(-sum(gross_amount) filter(where entry_type='refund'),2),0),coalesce(round(sum(commission_amount),2),0) into v_gross,v_refund,v_commission from public.salon_performance_ledger where organization_id=p_organization_id and store_id=p_store_id and staff_id=p_staff_id and (occurred_at at time zone v_timezone)::date>=p_month and (occurred_at at time zone v_timezone)::date<(p_month+interval '1 month')::date;v_total:=round(v_staff.base_salary+v_commission+coalesce(p_bonus,0)-coalesce(p_deduction,0),2);begin insert into public.salon_payroll_runs(organization_id,store_id,staff_id,payroll_month,base_salary,gross_performance,refund_performance,net_performance,commission_total,bonus,deduction,payable_total,adjustment_reason,generated_by_staff_id) values(p_organization_id,p_store_id,p_staff_id,p_month,v_staff.base_salary,v_gross,v_refund,v_gross-v_refund,v_commission,round(coalesce(p_bonus,0),2),round(coalesce(p_deduction,0),2),v_total,btrim(coalesce(p_reason,'')),p_actor_staff_id) returning id into v_id;exception when unique_violation then raise exception '该员工本月工资已经生成';end;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'payroll',v_id::text,'generate',jsonb_build_object('staffId',p_staff_id,'month',p_month,'commission',v_commission,'payable',v_total),btrim(coalesce(p_reason,'')));v_response:=jsonb_build_object('payrollId',v_id,'status','draft','commissionTotal',v_commission,'payableTotal',v_total);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_review_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_payroll_id bigint,p_request_key text,p_decision text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_payroll public.salon_payroll_runs;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','approve');if p_decision not in('approved','rejected') or nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception '工资审批决定或意见无效';end if;v_op:=salon_private.claim_staff_request(p_organization_id,p_store_id,p_request_key,'payroll_review','payroll_'||p_decision,p_payroll_id,p_actor_staff_id,jsonb_build_object('p_actor_staff_id',p_actor_staff_id,'p_organization_id',p_organization_id,'p_store_id',p_store_id,'p_payroll_id',p_payroll_id,'p_decision',p_decision,'p_reason',p_reason),'payroll','approve');if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_payroll from public.salon_payroll_runs where organization_id=p_organization_id and store_id=p_store_id and id=p_payroll_id for update;if not found or v_payroll.status<>'draft' then raise exception '工资单不存在或当前不可审批';end if;if v_payroll.generated_by_staff_id=p_actor_staff_id then raise exception '工资单生成与审批不能为同一人';end if;update public.salon_payroll_runs set status=p_decision,reviewed_by_staff_id=p_actor_staff_id,review_reason=btrim(p_reason),reviewed_at=now() where organization_id=p_organization_id and id=p_payroll_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'payroll',p_payroll_id::text,'review',jsonb_build_object('status','draft'),jsonb_build_object('status',p_decision),btrim(p_reason));v_response:=jsonb_build_object('payrollId',p_payroll_id,'status',p_decision);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;
